import data from '@/shared/generated/licenses.json';

export interface LicensedPackage {
  name: string;
  version: string;
  license: string;
  repository: string | null;
  /** Key into `texts`; null when the package ships no licence file. */
  textId: string | null;
  /** Set when the package ships no licence file and the text was built from the declared licence's standard wording. */
  generatedFrom?: string;
  /** Set when the generated notice names no declared copyright holder. */
  holderInferred?: boolean;
}

/** Generated by `npm run gen:licenses`. Each distinct licence text is stored once and referenced by id. */
export const packages: readonly LicensedPackage[] = data.packages;
export const texts: Readonly<Record<string, string>> = data.texts;
